def delete(self, request: Request, user: User, notification_option_id: str) -> Response:
    try:
        option = NotificationSettingOption.objects.get(
            id=notification_option_id,
        )
    except NotificationSettingOption.DoesNotExist:
        return Response(status=status.HTTP_404_NOT_FOUND)

    option.delete()
    return Response(status=status.HTTP_204_NO_CONTENT)

class UserEndpoint(Endpoint):
    """
    The base endpoint for APIs that deal with Users. Inherit from this class to
    get permission checks and to automatically convert user ID "me" to the
    currently logged in user's ID.
    """

    permission_classes = (UserPermission,)

    def convert_args(self, request: Request, user_id, *args, **kwargs):
        if user_id == "me":
            if not request.user.is_authenticated:
                raise ResourceDoesNotExist
            user_id = request.user.id

        try:
            user = User.objects.get(id=user_id)
        except (User.DoesNotExist, ValueError):
            raise ResourceDoesNotExist

        self.check_object_permissions(request, user)

        kwargs["user"] = user
        return args, kwargs

@control_silo_only_model
class NotificationSettingOption(NotificationSettingBase):
    __include_in_export__ = False

    class Meta:
        app_label = "sentry"
        db_table = "sentry_notificationsettingoption"
        unique_together = (
            (
                "scope_type",
                "scope_identifier",
                "user_id",
                "team_id",
                "type",
            ),
        )
        constraints = [
            models.CheckConstraint(
                check=models.Q(team_id__isnull=False, user_id__isnull=True)
                | models.Q(team_id__isnull=True, user_id__isnull=False),
                name="notification_setting_option_team_or_user_check",
            )
        ]

